"""Pipeline helpers used by sklearn-pandas."""

from sklearn.pipeline import Pipeline, _name_estimators

try:
    from sklearn.utils import tosequence
except ImportError:  # pragma: no cover
    def tosequence(values):
        if isinstance(values, list):
            return values
        return list(values)


def _call_fit(fit_method, X, y=None, **kwargs):
    """Call ``fit``/``fit_transform`` with or without ``y`` as needed."""
    try:
        return fit_method(X, y, **kwargs)
    except TypeError:
        return fit_method(X, **kwargs)


class TransformerPipeline(Pipeline):
    """
    Pipeline that expects all steps to be transformers taking a single X
    argument, an optional y argument, and having fit and transform methods.
    """

    def __init__(self, steps):
        names, estimators = zip(*steps)
        if len(dict(steps)) != len(steps):
            raise ValueError("Provided step names are not unique: %s" % (names,))

        estimator = estimators[-1]
        for transformer in estimators:
            if (not (hasattr(transformer, "fit") or hasattr(transformer, "fit_transform"))
                    or not hasattr(transformer, "transform")):
                raise TypeError(
                    "All steps of the chain should be transforms and implement "
                    "fit and transform '%s' (type %s) doesn't)"
                    % (transformer, type(transformer))
                )

        if not hasattr(estimator, "fit"):
            raise TypeError(
                "Last step of chain should implement fit '%s' (type %s) doesn't)"
                % (estimator, type(estimator))
            )

        super().__init__(tosequence(steps))

    def _pre_transform(self, X, y=None, **fit_params):
        """Pre-transform the data by fitting intermediate transformers."""
        fit_params_steps = {step: {} for step, _ in self.steps}
        for pname, pval in fit_params.items():
            step, param = pname.split("__", 1)
            fit_params_steps[step][param] = pval

        Xt = X
        for name, transform in self.steps[:-1]:
            if hasattr(transform, "fit_transform"):
                Xt = _call_fit(transform.fit_transform, Xt, y, **fit_params_steps[name])
            else:
                Xt = _call_fit(transform.fit, Xt, y, **fit_params_steps[name]).transform(Xt)
        return Xt, fit_params_steps[self.steps[-1][0]]

    def fit(self, X, y=None, **fit_params):
        """Fit all transformers in the pipeline."""
        Xt, fit_params = self._pre_transform(X, y, **fit_params)
        _call_fit(self.steps[-1][-1].fit, Xt, y, **fit_params)
        return self

    def fit_transform(self, X, y=None, **fit_params):
        """Fit the pipeline and return transformed output."""
        Xt, fit_params = self._pre_transform(X, y, **fit_params)
        last = self.steps[-1][-1]
        if hasattr(last, "fit_transform"):
            return _call_fit(last.fit_transform, Xt, y, **fit_params)
        return _call_fit(last.fit, Xt, y, **fit_params).transform(Xt)


def make_transformer_pipeline(*steps):
    """Construct a :class:`TransformerPipeline` from estimators."""
    return TransformerPipeline(_name_estimators(steps))

