"""Feature definition helpers for DataFrameMapper."""


def gen_features(columns, classes=None, prefix="", suffix=""):
    """Generate feature definitions consumable by :class:`DataFrameMapper`."""
    options = {}
    if prefix:
        options["prefix"] = prefix
    if suffix:
        options["suffix"] = suffix

    if classes is None:
        if options:
            return [(column, None, options.copy()) for column in columns]
        return [(column, None) for column in columns]

    normalized_classes = [definition for definition in classes if definition is not None]
    feature_defs = []

    for column in columns:
        column_options = options.copy()
        if not normalized_classes:
            feature_defs.append((column, None, column_options))
            continue

        feature_transformers = []
        for definition in normalized_classes:
            if isinstance(definition, dict):
                params = definition.copy()
                klass = params.pop("class")
                feature_transformers.append(klass(**params))
            else:
                feature_transformers.append(definition())

        feature_defs.append((column, feature_transformers or None, column_options))

    return feature_defs

