"""Custom transformers provided by sklearn-pandas."""

import warnings

import numpy as np
import pandas as pd
from sklearn.base import TransformerMixin


def _get_mask(X, value):
    """Compute the boolean mask ``X == value`` with NaN handling."""
    if value == "NaN" or value is None or (isinstance(value, float) and np.isnan(value)):
        return pd.isnull(X)
    return X == value


class NumericalTransformer(TransformerMixin):
    """
    Provides commonly used numerical transformers.
    """

    SUPPORTED_FUNCTIONS = ["log", "log1p"]

    def __init__(self, func):
        warnings.warn(
            """
            NumericalTransformer will be deprecated in 3.0 version.
            Please use Sklearn.base.TransformerMixin to write
            customer transformers
            """,
            DeprecationWarning,
        )
        assert func in self.SUPPORTED_FUNCTIONS, (
            f"Only following func are supported: {self.SUPPORTED_FUNCTIONS}"
        )
        super().__init__()
        self.__func = func

    def fit(self, X, y=None):
        return self

    def _coerce_numeric(self, X):
        if isinstance(X, (pd.Series, pd.DataFrame)):
            try:
                numeric = X if all(pd.api.types.is_numeric_dtype(dtype) for dtype in X.dtypes) else X.astype(float)
            except AttributeError:
                numeric = X if pd.api.types.is_numeric_dtype(X.dtype) else X.astype(float)
            except (TypeError, ValueError) as exc:
                raise TypeError("NumericalTransformer only supports numeric input.") from exc
            values = numeric.to_numpy()
            return numeric, values

        numeric = np.asarray(X)
        if not np.issubdtype(numeric.dtype, np.number):
            try:
                numeric = numeric.astype(float)
            except (TypeError, ValueError) as exc:
                raise TypeError("NumericalTransformer only supports numeric input.") from exc
        return numeric, np.asarray(numeric)

    def transform(self, X, y=None):
        numeric, values = self._coerce_numeric(X)

        if self.__func == "log":
            invalid = (values <= 0) & ~pd.isnull(values)
            if np.any(invalid):
                raise ValueError(
                    "NumericalTransformer('log') requires all non-missing values "
                    "to be strictly positive."
                )
            return np.log(numeric)

        if self.__func == "log1p":
            invalid = (values < -1) & ~pd.isnull(values)
            if np.any(invalid):
                raise ValueError(
                    "NumericalTransformer('log1p') requires all non-missing "
                    "values to be greater than or equal to -1."
                )
            return np.log1p(numeric)

        raise ValueError(f"Invalid function name: {self.__func}")

