"""Map pandas DataFrame columns to sklearn transformers."""

import contextlib
from datetime import datetime

import numpy as np
import pandas as pd
from scipy import sparse
from sklearn.base import BaseEstimator, TransformerMixin

from . import logger
from .cross_validation import DataWrapper
from .pipeline import TransformerPipeline, _call_fit, make_transformer_pipeline

string_types = text_type = str


def _handle_feature(fea):
    """
    Convert 1-dimensional arrays to 2-dimensional column vectors.
    """
    if len(fea.shape) == 1:
        fea = np.array([fea]).T
    return fea


def _build_transformer(transformers):
    if isinstance(transformers, list):
        transformers = make_transformer_pipeline(*transformers)
    return transformers


def _build_feature(columns, transformers, options=None, X=None):
    options = {} if options is None else options
    if X is None:
        return (columns, _build_transformer(transformers), options)
    return (
        columns(X) if callable(columns) else columns,
        _build_transformer(transformers),
        options,
    )


def _elapsed_secs(t1):
    return (datetime.now() - t1).total_seconds()


def _get_feature_names(estimator):
    """Attempt to extract feature names from a fitted estimator."""
    if hasattr(estimator, "classes_"):
        return estimator.classes_

    for attr in ("get_feature_names_out", "get_feature_names"):
        if not hasattr(estimator, attr):
            continue

        getter = getattr(estimator, attr)
        try:
            names = getter()
        except TypeError:
            try:
                names = getter(None)
            except TypeError:
                continue

        if names is not None:
            return list(names)

    return None


@contextlib.contextmanager
def add_column_names_to_exception(column_names):
    """Append the current column selection to an exception message."""
    try:
        yield
    except Exception as ex:
        if ex.args:
            msg = u"{}: {}".format(column_names, ex.args[0])
        else:
            msg = text_type(column_names)
        ex.args = (msg,) + ex.args[1:]
        raise


def _iter_features(features):
    if features is None:
        return []
    if isinstance(features, list):
        return features
    return [features]


class DataFrameMapper(BaseEstimator, TransformerMixin):
    """
    Map Pandas data frame column subsets to their own sklearn transformation.
    """

    def __init__(self, features, default=False, sparse=False, df_out=False,
                 input_df=False, drop_cols=None):
        self.features = features
        self.default = default
        self.built_default = None
        self.sparse = sparse
        self.df_out = df_out
        self.input_df = input_df
        self.drop_cols = [] if drop_cols is None else drop_cols
        self.transformed_names_ = []
        if df_out and (sparse or default):
            raise ValueError("Can not use df_out with sparse or default")

    def _build(self, X=None):
        """Build ``built_features`` and ``built_default``."""
        self.built_features = [_build_feature(*feature, X=X) for feature in _iter_features(self.features)]
        self.built_default = _build_transformer(self.default)

    @property
    def _selected_columns(self):
        """Return a set of explicitly selected columns."""
        selected_columns = set()
        source = getattr(self, "built_features", None)
        if source is None:
            source = _iter_features(self.features)

        for feature in source:
            columns = feature[0]
            if callable(columns):
                continue
            if isinstance(columns, list):
                selected_columns.update(columns)
            else:
                selected_columns.add(columns)
        return selected_columns

    def _unselected_columns(self, X):
        """
        Return list of columns present in X and not selected explicitly.
        """
        X_columns = list(X.columns)
        return [
            column for column in X_columns
            if column not in self._selected_columns and column not in self.drop_cols
        ]

    def __setstate__(self, state):
        super().__setstate__(state)
        self.features = [_build_feature(*feat) for feat in state["features"]]
        self.sparse = state.get("sparse", False)
        self.default = state.get("default", False)
        self.df_out = state.get("df_out", False)
        self.input_df = state.get("input_df", False)
        self.drop_cols = state.get("drop_cols", [])
        self.built_features = state.get("built_features", state.get("build_features", self.features))
        self.built_default = state.get("built_default", self.default)
        self.transformed_names_ = state.get("transformed_names_", [])

    def __getstate__(self):
        state = super().__getstate__()
        state["features"] = self.features
        state["sparse"] = self.sparse
        state["default"] = self.default
        state["df_out"] = self.df_out
        state["input_df"] = self.input_df
        state["drop_cols"] = self.drop_cols
        state["built_features"] = getattr(self, "built_features", None)
        state["built_default"] = self.built_default
        state["transformed_names_"] = self.transformed_names_
        return state

    def _get_col_subset(self, X, cols, input_df=False):
        """
        Get a subset of columns from X.
        """
        if isinstance(X, list):
            if callable(cols):
                X = pd.DataFrame(X)
                cols = cols(X)
            else:
                X = pd.DataFrame([x[cols] for x in X])
        elif isinstance(X, DataWrapper):
            X = X.df

        if callable(cols):
            cols = cols(X)

        if isinstance(cols, string_types):
            return_vector = True
            cols = [cols]
        else:
            return_vector = False

        if return_vector:
            subset = X[cols[0]]
        else:
            subset = X[cols]

        if input_df:
            return subset
        return subset.values

    def fit(self, X, y=None):
        """Fit each configured transformer."""
        self._build(X=X)

        for columns, transformers, options in self.built_features:
            t1 = datetime.now()
            input_df = options.get("input_df", self.input_df)

            if transformers is not None:
                with add_column_names_to_exception(columns):
                    Xt = self._get_col_subset(X, columns, input_df)
                    _call_fit(transformers.fit, Xt, y)
            logger.info("[FIT] %s: %s secs", columns, _elapsed_secs(t1))

        if self.built_default is not False and self.built_default is not None:
            unsel_cols = self._unselected_columns(X)
            if unsel_cols:
                with add_column_names_to_exception(unsel_cols):
                    Xt = self._get_col_subset(X, unsel_cols, self.input_df)
                    _call_fit(self.built_default.fit, Xt, y)
        return self

    def get_names(self, columns, transformer, x, alias=None, prefix="", suffix=""):
        """Return verbose names for transformed columns."""
        if alias is not None:
            name = alias
        elif isinstance(columns, list):
            name = "_".join(map(str, columns))
        else:
            name = columns

        num_cols = x.shape[1] if len(x.shape) > 1 else 1
        output = []

        if num_cols > 1:
            if isinstance(transformer, TransformerPipeline):
                inverse_steps = transformer.steps[::-1]
                estimators = (estimator for _, estimator in inverse_steps)
                names_steps = (_get_feature_names(estimator) for estimator in estimators)
                names = next((names for names in names_steps if names is not None), None)
            else:
                names = _get_feature_names(transformer)

            if names is not None and len(names) == num_cols:
                output = [f"{name}_{out_name}" for out_name in names]
            else:
                output = [name + "_" + str(index) for index in range(num_cols)]
        else:
            output = [name]

        if not prefix and not suffix:
            return output
        return ["{}{}{}".format(prefix, out_name, suffix) for out_name in output]

    def get_dtypes(self, extracted):
        dtypes_features = [self.get_dtype(extracted_feature) for extracted_feature in extracted]
        return [dtype for dtype_feature in dtypes_features for dtype in dtype_feature]

    def get_dtype(self, ex):
        if isinstance(ex, np.ndarray) or sparse.issparse(ex):
            return [ex.dtype] * ex.shape[1]
        if isinstance(ex, pd.DataFrame):
            return list(ex.dtypes)
        raise TypeError(type(ex))

    def _transform(self, X, y=None, do_fit=False):
        """
        Transform the given data with optional fit in advance.
        """
        if do_fit:
            self._build(X=X)

        extracted = []
        transformed_names_ = []

        for columns, transformers, options in self.built_features:
            input_df = options.get("input_df", self.input_df)
            Xt = self._get_col_subset(X, columns, input_df)

            if transformers is not None:
                with add_column_names_to_exception(columns):
                    if do_fit and hasattr(transformers, "fit_transform"):
                        t1 = datetime.now()
                        Xt = _call_fit(transformers.fit_transform, Xt, y)
                        logger.info("[FIT_TRANSFORM] %s: %s secs", columns, _elapsed_secs(t1))
                    else:
                        if do_fit:
                            t1 = datetime.now()
                            _call_fit(transformers.fit, Xt, y)
                            logger.info("[FIT] %s: %s secs", columns, _elapsed_secs(t1))

                        t1 = datetime.now()
                        Xt = transformers.transform(Xt)
                        logger.info("[TRANSFORM] %s: %s secs", columns, _elapsed_secs(t1))

            extracted.append(_handle_feature(Xt))

            alias = options.get("alias")
            prefix = options.get("prefix", "")
            suffix = options.get("suffix", "")
            transformed_names_ += self.get_names(columns, transformers, Xt, alias, prefix, suffix)

        if self.built_default is not False:
            unsel_cols = self._unselected_columns(X)
            if unsel_cols:
                Xt = self._get_col_subset(X, unsel_cols, self.input_df)
                if self.built_default is not None:
                    with add_column_names_to_exception(unsel_cols):
                        if do_fit and hasattr(self.built_default, "fit_transform"):
                            Xt = _call_fit(self.built_default.fit_transform, Xt, y)
                        else:
                            if do_fit:
                                _call_fit(self.built_default.fit, Xt, y)
                            Xt = self.built_default.transform(Xt)
                    transformed_names_ += self.get_names(unsel_cols, self.built_default, Xt)
                else:
                    transformed_names_ += unsel_cols

                extracted.append(_handle_feature(Xt))

        self.transformed_names_ = transformed_names_

        if not extracted:
            if self.sparse:
                stacked = sparse.csr_matrix((len(X), 0))
            else:
                stacked = np.empty((len(X), 0))
        elif any(sparse.issparse(feature) for feature in extracted):
            stacked = sparse.hstack(extracted).tocsr()
            if not self.sparse:
                stacked = stacked.toarray()
        else:
            stacked = np.hstack(extracted)

        if self.df_out:
            index = X.index if len(X) == len(stacked) else None
            dtypes = self.get_dtypes(extracted)
            df_out = pd.DataFrame(stacked, columns=self.transformed_names_, index=index)
            for col, dtype in zip(self.transformed_names_, dtypes):
                df_out[col] = df_out[col].astype(dtype)
            return df_out

        return stacked

    def transform(self, X):
        """Transform the given data."""
        return self._transform(X)

    def fit_transform(self, X, y=None):
        """Fit the mapper and return transformed data."""
        return self._transform(X, y, True)

